{"path":"/workspace/lib/store.js","content":"import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, unlink, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

const LIMITS = {
  title: 300,
  author: 200,
  notes: 20000,
};

export function createStore(filePath) {
  let queue = Promise.resolve();

  function enqueue(task) {
    const run = queue.then(task, task);
    queue = run.then(
      () => {},
      () => {},
    );
    return run;
  }

  async function read() {
    let raw;
    try {
      raw = await readFile(filePath, 'utf8');
    } catch (err) {
      if (err && err.code === 'ENOENT') return [];
      throw err;
    }
    if (!raw.trim()) return [];
    const data = JSON.parse(raw);
    if (!Array.isArray(data)) {
      throw new Error('Books file must be a JSON array');
    }
    return data;
  }

  async function write(books) {
    await mkdir(dirname(filePath), { recursive: true });
    const tmp = `${filePath}.${randomUUID()}.tmp`;
    try {
      await writeFile(tmp, `${JSON.stringify(books, null, 2)}\n`, 'utf8');
      await rename(tmp, filePath);
    } catch (err) {
      await unlink(tmp).catch(() => {});
      throw err;
    }
  }

  return {
    filePath,
    limits: LIMITS,

    ensure() {
      return enqueue(async () => {
        try {
          await readFile(filePath, 'utf8');
        } catch (err) {
          if (err && err.code === 'ENOENT') {
            await write([]);
            return;
          }
          throw err;
        }
      });
    },

    list() {
      return enqueue(() => read());
    },

    async get(id) {
      const books = await this.list();
      return findBook(books, id);
    },

    add({ title, author, notes }) {
      return enqueue(async () => {
        const books = await read();
        const book = {
          id: randomUUID(),
          title: clean(title, LIMITS.title),
          author: clean(author, LIMITS.author),
          notes: clean(notes, LIMITS.notes),
          status: 'reading',
          createdAt: new Date().toISOString(),
          finishedAt: null,
        };
        books.unshift(book);
        await write(books);
        return book;
      });
    },

    finish(id) {
      return enqueue(async () => {
        const books = await read();
        const book = findBook(books, id);
        if (!book) return null;
        if (book.status !== 'finished') {
          book.status = 'finished';
          book.finishedAt = new Date().toISOString();
          await write(books);
        }
        return book;
      });
    },

    updateNotes(id, notes) {
      return enqueue(async () => {
        const books = await read();
        const book = findBook(books, id);
        if (!book) return null;
        book.notes = clean(notes, LIMITS.notes);
        await write(books);
        return book;
      });
    },
  };
}

export function validateBookInput(input, limits = LIMITS) {
  const title = typeof input.title === 'string' ? input.title.trim() : '';
  const author = typeof input.author === 'string' ? input.author.trim() : '';
  const notes = typeof input.notes === 'string' ? input.notes.trim() : '';
  const errors = [];
  if (!title) errors.push('Title is required.');
  else if (title.length > limits.title) errors.push('Title is too long.');
  if (!author) errors.push('Author is required.');
  else if (author.length > limits.author) errors.push('Author is too long.');
  if (notes.length > limits.notes) errors.push('Notes are too long.');
  return { title, author, notes, errors };
}

function clean(value, max) {
  const text = typeof value === 'string' ? value.trim() : '';
  return text.slice(0, max);
}

function findBook(books, id) {
  return books.find((book) => book && book.id === id) ?? null;
}
"}

{"path":"/workspace/lib/html.js","content":"export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

export function homePage({ reading, finished, error, form }) {
  const values = {
    title: form?.title ?? '',
    author: form?.author ?? '',
    notes: form?.notes ?? '',
  };
  return layout({
    title: 'Books',
    body: `
      <header class="mast">
        <h1>Books</h1>
        <p class="lede">What you're reading now, and what you've finished.</p>
      </header>
      ${sectionList('reading-heading', 'Currently reading', reading, true)}
      ${sectionList('finished-heading', 'Finished', finished, false)}
      <section class="panel" aria-labelledby="add-heading">
        <h2 id="add-heading">Add a book</h2>
        ${error ? `<p class="error" role="alert">${escapeHtml(error)}</p>` : ''}
        <form id="add-book" method="post" action="/books" accept-charset="UTF-8">
          <label for="title">Title
            <input id="title" name="title" required maxlength="300" value="${escapeHtml(values.title)}">
          </label>
          <label for="author">Author
            <input id="author" name="author" required maxlength="200" value="${escapeHtml(values.author)}">
          </label>
          <label for="notes">Notes
            <textarea id="notes" name="notes" rows="4" maxlength="20000">${escapeHtml(values.notes)}</textarea>
          </label>
          <button type="submit">Add book</button>
        </form>
      </section>
    `,
  });
}

export function bookPage(book, { shareUrl }) {
  const finished = book.status === 'finished';
  const notes = book.notes?.trim()
    ? `<div class="notes">${escapeHtml(book.notes)}</div>`
    : '<p class="empty">No notes yet.</p>';
  const finishForm = finished
    ? `<p class="status">Finished${book.finishedAt ? ` ${escapeHtml(formatDate(book.finishedAt))}` : ''}</p>`
    : `<p class="status">Reading</p>
       <form method="post" action="${bookPath(book.id)}/finish" accept-charset="UTF-8">
         <input type="hidden" name="next" value="${bookPath(book.id)}">
         <button type="submit">Mark as finished</button>
       </form>`;

  return layout({
    title: `${book.title} — Books`,
    body: `
      <p class="back"><a href="/">All books</a></p>
      <article>
        <h1>${escapeHtml(book.title)}</h1>
        <p class="by">by ${escapeHtml(book.author)}</p>
        ${finishForm}
        <section class="panel" aria-labelledby="notes-heading">
          <h2 id="notes-heading">Notes</h2>
          ${notes}
          <form method="post" action="${bookPath(book.id)}/notes" accept-charset="UTF-8">
            <label for="book-notes">Update notes
              <textarea id="book-notes" name="notes" rows="6" maxlength="20000">${escapeHtml(book.notes ?? '')}</textarea>
            </label>
            <button class="quiet" type="submit">Save notes</button>
          </form>
        </section>
        <section class="panel" aria-labelledby="share-heading">
          <h2 id="share-heading">Share</h2>
          <p class="hint">Send this link to someone. It opens this book.</p>
          <label for="share-link">Link to this book
            <input id="share-link" readonly value="${escapeHtml(shareUrl)}" onclick="this.select()">
          </label>
        </section>
      </article>
    `,
  });
}

export function messagePage({ title, message, statusText }) {
  return layout({
    title,
    body: `
      <h1>${escapeHtml(title)}</h1>
      <p>${escapeHtml(message)}</p>
      ${statusText ? '' : ''}
      <p class="back"><a href="/">All books</a></p>
    `,
  });
}

function sectionList(headingId, heading, books, canFinish) {
  const items = books.length
    ? `<ul class="books">${books.map((book) => bookItem(book, canFinish)).join('')}</ul>`
    : '<p class="empty">None yet.</p>';
  return `
    <section class="panel" aria-labelledby="${headingId}">
      <h2 id="${headingId}">${heading}</h2>
      ${items}
    </section>
  `;
}

function bookItem(book, canFinish) {
  const path = bookPath(book.id);
  const finish = canFinish
    ? `<form method="post" action="${path}/finish" accept-charset="UTF-8">
         <input type="hidden" name="next" value="/">
         <button type="submit">Mark as finished</button>
       </form>`
    : '';
  return `
    <li class="book">
      <div>
        <a class="title" href="${path}">${escapeHtml(book.title)}</a>
        <span class="by">by ${escapeHtml(book.author)}</span>
      </div>
      ${finish}
    </li>
  `;
}

function bookPath(id) {
  return `/books/${encodeURIComponent(id)}`;
}

function formatDate(iso) {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    timeZone: 'UTC',
  });
}

