{"path":"/workspace/lib/handler.js","content":"import { bookPage, homePage, messagePage } from './html.js';
import { validateBookInput } from './store.js';

export function createHandler(store) {
  return async function handler(req, res) {
    try {
      await route(req, res, store);
    } catch (err) {
      console.error(err);
      if (!res.headersSent) {
        sendHtml(res, 500, messagePage({
          title: 'Something went wrong',
          message: 'The book list could not be read. Check the JSON file and try again.',
        }));
      }
    }
  };
}

async function route(req, res, store) {
  const url = new URL(req.url || '/', 'http://localhost');
  const path = normalizePath(url.pathname);
  const method = req.method || 'GET';

  if (method === 'GET' && path === '/') {
    const books = await store.list();
    sendHtml(res, 200, homePage(splitBooks(books)));
    return;
  }

  if (method === 'POST' && path === '/books') {
    const input = await readInput(req);
    const validated = validateBookInput(input, store.limits);
    if (validated.errors.length) {
      const books = await store.list();
      sendHtml(res, 400, homePage({
        ...splitBooks(books),
        error: validated.errors.join(' '),
        form: validated,
      }));
      return;
    }
    const book = await store.add(validated);
    redirect(res, bookPath(book.id));
    return;
  }

  const notesMatch = path.match(/^\/books\/([^/]+)\/notes$/);
  if (notesMatch && method === 'POST') {
    const id = decodeId(notesMatch[1]);
    if (!id) return notFound(res);
    const input = await readInput(req);
    const notes = typeof input.notes === 'string' ? input.notes : '';
    if (notes.trim().length > store.limits.notes) {
      const book = await store.get(id);
      if (!book) return notFound(res);
      sendHtml(res, 400, bookPage({ ...book, notes }, {
        shareUrl: shareUrl(req, book.id),
      }));
      return;
    }
    const book = await store.updateNotes(id, notes);
    if (!book) return notFound(res);
    redirect(res, bookPath(book.id));
    return;
  }

  const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
  if (finishMatch && method === 'POST') {
    const id = decodeId(finishMatch[1]);
    if (!id) return notFound(res);
    const book = await store.finish(id);
    if (!book) return notFound(res);
    const input = await readInput(req);
    redirect(res, safeNext(input.next, bookPath(book.id)));
    return;
  }

  const bookMatch = path.match(/^\/books\/([^/]+)$/);
  if (bookMatch && method === 'GET') {
    const id = decodeId(bookMatch[1]);
    if (!id) return notFound(res);
    const book = await store.get(id);
    if (!book) return notFound(res);
    sendHtml(res, 200, bookPage(book, { shareUrl: shareUrl(req, book.id) }));
    return;
  }

  notFound(res);
}

function splitBooks(books) {
  const readable = books.filter((book) => book && typeof book.id === 'string' && book.title);
  const reading = readable
    .filter((book) => book.status !== 'finished')
    .sort(byDateDesc('createdAt'));
  const finished = readable
    .filter((book) => book.status === 'finished')
    .sort(byDateDesc('finishedAt'));
  return { reading, finished };
}

function byDateDesc(field) {
  return (a, b) => String(b[field] || '').localeCompare(String(a[field] || ''));
}

function bookPath(id) {
  return `/books/${encodeURIComponent(id)}`;
}

function shareUrl(req, id) {
  return `${requestOrigin(req)}${bookPath(id)}`;
}

function requestOrigin(req) {
  const host = safeHost(req.headers.host);
  let proto = 'http';
  const forwarded = req.headers['x-forwarded-proto'];
  if (typeof forwarded === 'string') {
    const first = forwarded.split(',')[0].trim().toLowerCase();
    if (first === 'http' || first === 'https') proto = first;
  }
  return `${proto}://${host}`;
}

function safeHost(host) {
  if (typeof host !== 'string') return 'localhost';
  if (/^[A-Za-z0-9.-]+(?::\d{1,5})?$/.test(host)) return host;
  if (/^\[[0-9A-Fa-f:.]+\](?::\d{1,5})?$/.test(host)) return host;
  return 'localhost';
}

function safeNext(value, fallback) {
  if (typeof value !== 'string') return fallback;
  if (!value.startsWith('/') || value.startsWith('//') || value.includes('\\') || value.includes('\r') || value.includes('\n')) {
    return fallback;
  }
  return value;
}

function decodeId(raw) {
  try {
    const id = decodeURIComponent(raw);
    if (!id || id.length > 80 || /[\u0000-\u001f\u007f/\\]/.test(id)) return null;
    return id;
  } catch {
    return null;
  }
}

function normalizePath(pathname) {
  if (pathname.length > 1 && pathname.endsWith('/')) return pathname.slice(0, -1);
  return pathname;
}

async function readInput(req) {
  const raw = await readBody(req);
  const type = String(req.headers['content-type'] || '');
  if (!raw) return {};
  if (type.includes('application/json')) {
    const data = JSON.parse(raw);
    if (!data || typeof data !== 'object' || Array.isArray(data)) {
      throw Object.assign(new Error('Expected a JSON object'), { status: 400 });
    }
    return data;
  }
  return Object.fromEntries(new URLSearchParams(raw));
}

async function readBody(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > 1_000_000) {
      throw Object.assign(new Error('Body too large'), { status: 413 });
    }
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf8');
}

function notFound(res) {
  sendHtml(res, 404, messagePage({
    title: 'Book not found',
    message: "That book isn't on the list.",
  }));
}

function sendHtml(res, status, html) {
  const body = html;
  res.writeHead(status, {
    'content-type': 'text/html; charset=utf-8',
    'content-length': Buffer.byteLength(body),
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
  });
  res.end(body);
}

function redirect(res, location) {
  res.writeHead(303, {
    location,
    'cache-control': 'no-store',
  });
  res.end();
}
"}

{"path":"/workspace/server.js","content":"import { createServer } from 'node:http';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createHandler } from './lib/handler.js';
import { createStore } from './lib/store.js';

const root = dirname(fileURLToPath(import.meta.url));
const filePath = process.env.BOOKS_FILE || join(root, 'data', 'books.json');
const port = Number(process.env.PORT || 3000);
const host = process.env.HOST || '0.0.0.0';

if (!Number.isInteger(port) || port < 1 || port > 65535) {
  console.error('PORT must be an integer from 1 to 65535');
  process.exit(1);
}

const store = createStore(filePath);
const server = createServer(createHandler(store));

server.on('error', (err) => {
  console.error(err.message);
  process.exit(1);
});

await store.ensure();
server.listen(port, host, () => {
  console.log(`Book tracker at http://localhost:${port}`);
  console.log(`Books file: ${filePath}`);
});
"}

{"path":"/workspace/test/books.test.js","content":"import { createServer } from 'node:http';
import { mkdtemp, readFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, describe, expect, it } from 'vitest';
import { createHandler } from '../lib/handler.js';
import { createStore } from '../lib/store.js';

const servers = [];

afterEach(async () => {
  await Promise.all(servers.splice(0).map((server) => new Promise((resolve) => server.close(resolve))));
});

describe('book tracker', () => {
  it('shows current and finished books, then a shareable book page', async () => {
    const { base, store } = await start();

    const created = await postForm(`${base}/books`, {
      title: 'The Dispossessed',
      author: 'Ursula K. Le Guin',
      notes: 'Notes about <Shevek> & the wall.',
    });
    expect(created.status).toBe(303);
    const location = created.headers.get('location');
    expect(location).toMatch(/^\/books\/[0-9a-f-]{36}$/i);

    const detail = await fetch(`${base}${location}`);
    expect(detail.status).toBe(200);
    const detailHtml = await detail.text();
    expect(detailHtml).toContain('The Dispossessed');
    expect(detailHtml).toContain('Ursula K. Le Guin');
    expect(detailHtml).toContain('Notes about &lt;Shevek&gt; &amp; the wall.');
    expect(detailHtml).toContain(`${base}${location}`);
    expect(detailHtml).not.toContain('<Shevek>');

    const home = await fetch(`${base}/`);
    const homeHtml = await home.text();
    const reading = section(homeHtml, 'reading-heading', 'finished-heading');
    const finished = section(homeHtml, 'finished-heading', 'add-heading');
    expect(reading).toContain('Currently reading');
    expect(reading).toContain('The Dispossessed');
    expect(reading).toContain('href="' + location + '"');
    expect(finished).toContain('Finished');
    expect(finished).not.toContain('The Dispossessed');

    const marked = await postForm(`${base}${location}/finish`, { next: '/' });
    expect(marked.status).toBe(303);
    expect(marked.headers.get('location')).toBe('/');

    const after = await (await fetch(`${base}/`)).text();
    expect(section(after, 'reading-heading', 'finished-heading')).not.toContain('The Dispossessed');
    expect(section(after, 'finished-heading', 'add-heading')).toContain('The Dispossessed');

    const saved = JSON.parse(await readFile(store.filePath, 'utf8'));
    expect(saved).toHaveLength(1);
    expect(saved[0]).toMatchObject({
      title: 'The Dispossessed',
      author: 'Ursula K. Le Guin',
      status: 'finished',
    });
    expect(saved[0].finishedAt).toEqual(expect.any(String));
  });

  it('keeps books after a new store opens the same file', async () => {
    const dir = await mkdtemp(join(tmpdir(), 'books-'));
    const filePath = join(dir, 'books.json');
    const first = createStore(filePath);
    const book = await first.add({
      title: 'Kindred',
      author: 'Octavia Butler',
      notes: 'Time travel as history.',
    });

    const restarted = createStore(filePath);
    const loaded = await restarted.get(book.id);
    expect(loaded).toMatchObject({
      title: 'Kindred',
      author: 'Octavia Butler',
      notes: 'Time travel as history.',
      status: 'reading',
    });
  });

  it('rejects a book with no title and does not write it', async () => {
    const { base, store } = await start();
    const response = await postForm(`${base}/books`, { title: '   ', author: 'Someone', notes: '' });
    expect(response.status).toBe(400);
    const html = await response.text();
    expect(html).toContain('Title is required.');
    expect(JSON.parse(await readFile(store.filePath, 'utf8'))).toEqual([]);
  });

  it('returns 404 for an unknown book link', async () => {
    const { base } = await start();
    const response = await fetch(`${base}/books/missing-book`);
    expect(response.status).toBe(404);
  });

  it('updates notes on the book page', async () => {
    const { base } = await start();
    const created = await postForm(`${base}/books`, {
      title: 'Parable of the Sower',
      author: 'Octavia Butler',
